        return Math.Min(rawScore / maxRaw * 100.0, 100.0);
    }
}

using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // --- CalculatePercentage: boundary checks with comparison assertions ---

    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        var result = _calculator.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_Returns0()
    {
        var result = _calculator.CalculatePercentage(0, 10);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ResultIsInRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        // Assert.IsInRange verifies: low <= actual <= high
        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(70.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_AlwaysReturnsNonNegative()
    {
        var result = _calculator.CalculatePercentage(1, 100);

        // Assert.IsGreaterThan verifies: actual > lowerBound
        Assert.IsGreaterThan(0.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_IsLessThan100()
    {
        var result = _calculator.CalculatePercentage(9, 10);

        // Assert.IsLessThan verifies: actual < upperBound
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // --- GetGrade: boundary tests at each grade threshold ---

    [TestMethod]
    [DataRow(90.0, "A", DisplayName = "Exact A boundary")]
    [DataRow(89.9, "B", DisplayName = "Just below A")]
    [DataRow(80.0, "B", DisplayName = "Exact B boundary")]
    [DataRow(79.9, "C", DisplayName = "Just below B")]
    [DataRow(70.0, "C", DisplayName = "Exact C boundary")]
    [DataRow(69.9, "D", DisplayName = "Just below C")]
    [DataRow(60.0, "D", DisplayName = "Exact D boundary")]
    [DataRow(59.9, "F", DisplayName = "Just below D")]
    [DataRow(0.0, "F", DisplayName = "Zero")]
    [DataRow(100.0, "A", DisplayName = "Perfect")]
    public void GetGrade_AtBoundary_ReturnsExpectedGrade(double percentage, string expected)
    {
        var grade = _calculator.GetGrade(percentage);
        Assert.AreEqual(expected, grade);
    }

    // --- NormalizeScore: boundary checks with comparison assertions ---

    [TestMethod]
    public void NormalizeScore_NormalInput_ResultIsInRange()
    {
        var result = _calculator.NormalizeScore(45.0, 50.0);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(90.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(120.0, 100.0);

        // Capped at 100 even though raw > max
        Assert.AreEqual(100.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ZeroRaw_Returns0()
    {
        var result = _calculator.NormalizeScore(0.0, 100.0);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_HalfRaw_IsGreaterThanZero()
    {
        var result = _calculator.NormalizeScore(50.0, 100.0);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }

    [TestMethod]
    public void NormalizeScore_NegativeMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, -10.0));
    }
}

